[
    {
        "role": "bullet_intro",
        "segment": "Difference between technical and business quality",
        "citations": []
    },
    {
        "role": "bullet",
        "segment": "Quality is viewed in terms of the products and services being provided by the business in which the software is embedded, rather than only the software itself.",
        "citations": [
            {
                "type": "source_text",
                "content": "When the focus of quality assessment is on products and processes, we usually measure quality with mathematical expressions involving faults, failures, and timing. Rarely is the scope broadened to include a business perspective, where quality is viewed in terms of the products and services being provided by the business in which the software is embedded.",
                "img_id": null
            }
        ]
    },
    {
        "role": "bullet",
        "segment": "We look at the technical value of our products, rather than more broadly at their business value.",
        "citations": [
            {
                "type": "source_text",
                "content": "That is, we look at the technical value of our products, rather than more broadly at their business value, and we make decisions based only on the resulting products' technical quality.",
                "img_id": null
            }
        ]
    },
    {
        "role": "bullet",
        "segment": "We often assume that improving technical quality will automatically translate into business value.",
        "citations": [
            {
                "type": "source_text",
                "content": "In other words, we assume that improving technical quality will automatically translate into business value.",
                "img_id": null
            }
        ]
    },
    {
        "role": "paragraph",
        "segment": "Why the distinction matters (why each is important)",
        "citations": []
    },
    {
        "role": "bullet",
        "segment": "Researchers have examined the relationships between business value and technical value to understand how they relate to decision making in organizations.",
        "citations": [
            {
                "type": "source_text",
                "content": "Several researchers have taken a close look at the relationships between business value and technical value.",
                "img_id": null
            }
        ]
    },
    {
        "role": "bullet",
        "segment": "Two frameworks help evaluate these kinds of resources—indicating why both technical and business value matter: a people maturity model for staff and a return-on-investment model for time and money.",
        "citations": [
            {
                "type": "source_text",
                "content": "In this section, we examine two frameworks for evaluating these kinds of resources: a people maturity model for staff and a return-on-investment model for time and money.",
                "img_id": null
            }
        ]
    },
    {
        "role": "bullet_intro",
        "segment": "Note on practical relevance",
        "citations": []
    },
    {
        "role": "bullet",
        "segment": "Understanding both perspectives helps align software quality decisions with business outcomes and ensures resources are applied where they create real value.",
        "citations": [
            {
                "type": "source_text",
                "content": "We must be able to evaluate whether we are using the appropriate levels of each. In this section, we examine two frameworks for evaluating these kinds of resources: a people maturity model for staff and a return-on-investment model for time and money.",
                "img_id": null
            }
        ]
    }
]

