[
    {
        "role": "paragraph",
        "segment": " Robertson and Robertson’s comprehensive requirements-definition template (described as accompanying the Volere process model) is designed to be used within the requirements process to elicit and check a set of requirements and to document them in the customer’s terms.",
        "citations": [
            {
                "type": "source_text",
                "content": "A  comprehensive  requirements-definition  template  developed  by  James  and Suzanne Robertson can be found at the Web site of the Atlantic Systems Guild: http:// www.systemsguild.com.This template is accompanied by a description of the Volere process model, which is a complete process for eliciting and checking a set of requirements.",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "The  requirements  definition  is  a  record  of  the  requirements  expressed  in  the  customer's terms.Working with the customer, we document what the customer can expect of the delivered system:",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "First, we outline the general purpose and scope of the system, including relevant benefits, objectives, and goals. References to other related systems are included, and we list any terms, designations, and abbreviations that may be useful.",
                "img_id": null
            }
        ],
        "type": null
    }
]

