    {
        "role": "bullet",
        "segment": "Use peer review as a key evidence source and treat reviews as systematic fault detection, not just a ritual.",
        "citations": [
            {
                "type": "source_text",
                "content": "peer review, the process whereby colleagues examine and comment on each other's designs and code, uncovered the remaining four out of five faults found",
